static void change_u16_endianness(uint8_t *dst, const uint8_t *src, unsigned size, unsigned be)
{
        unsigned convert = 0;
        unsigned i;
        uint8_t tmp;

#ifdef WORDS_BIGENDIAN
        if (!be)
                convert = 1;
#else
        if (be)
                convert = 1;
#endif

        /* convert to LE */
        if (convert) {
                for (i = 0; i < size; i += 2) {
                        tmp = src[i];
                        dst[i] = src[1 + i];
                        dst[1 + i] = tmp;
                }
        } else {
                if (dst != src)
                        memcpy(dst, src, size);
        }
}

